let passed = 0;
let failed = 0;

function test(name, actual, expected) {
  if (actual === expected) {
    console.log(`✓ ${name}`);
    passed++;
  } else {
    console.log(`✗ ${name}: got "${actual}", expected "${expected}"`);
    failed++;
  }
}

test('fizzbuzz(1) returns "1"', fizzbuzz(1), '1');
test('fizzbuzz(3) returns "Fizz"', fizzbuzz(3), 'Fizz');
test('fizzbuzz(5) returns "Buzz"', fizzbuzz(5), 'Buzz');
test('fizzbuzz(15) returns "FizzBuzz"', fizzbuzz(15), 'FizzBuzz');
test('fizzbuzz(4) returns "4"', fizzbuzz(4), '4');

console.log(`\n${passed} passed, ${failed} failed`);

process.exitCode = failed > 0 ? 1 : 0;
"}
